CATEGORIA_POR_NOMBRE = {'Pausado': 'pausado', 'Completado': 'finalizado', 'Cancelado': 'finalizado'}


def categorias_y_permisos(apps, schema_editor):
    """Los estados del sistema reciben su categoría, y «eliminar proyectos» pasa a «reabrir» con el
    mismo alcance, salvo «lo propio»: reabrir lo que uno mismo cerró no tiene sentido como permiso."""
    Estado = apps.get_model('Projects', 'Estado')
    for nombre, categoria in CATEGORIA_POR_NOMBRE.items():
        Estado.objects.filter(name=nombre).update(categoria=categoria)
    Roles = apps.get_model('Users', 'Roles')
    for rol in Roles.objects.all():
        permisos = dict(rol.permisos or {})
        alcance = permisos.pop('proyectos.eliminar', None)
        if alcance and alcance != 'propio':
            permisos.setdefault('proyectos.reabrir', alcance)
        if permisos != (rol.permisos or {}):
            rol.permisos = permisos
            rol.save(update_fields=['permisos'])


